verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..231c2b5 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,47 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: missing observed-model telemetry stays unknown even when every other
+// signal is strong. Trusted cost/duration/tokens and a signature-verified receipt must
+// never be laundered into a model match -- not for a pinned model, and not for the
+// null-model profile whose only passing path (MODEL_OBSERVATION_RECORDED) skips compare.
+const [legacyCodex] = profiles.synthesizeLegacyExecutors(['codex']);
+assert.equal(legacyCodex.model, null, 'legacy profile must exercise the null-model path');
+const modelessObservations = [
+  { trusted: true, cost: { amount: 1, unit: 'usd', source: 'adapter' }, duration_ms: 10, tokens: 5 },
+  { trusted: true, model: null, duration_ms: 10, tokens: 5 },
+  { trusted: true, model: '', duration_ms: 10, tokens: 5 },
+];
+for (const profile of [local, legacyCodex]) {
+  for (const observation of modelessObservations) {
+    assert.deepEqual(profiles.evaluateModelProof(profile, observation), {
+      requested_model: profile === local ? local.model : 'default',
+      observed_model: null,
+      status: 'unknown',
+      reason_code: 'MODEL_OBSERVATION_MISSING',
+    }, `${profile.profile_id} model proof leaked a verdict from telemetry without a model`);
+  }
+}
+
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+const modelessState = profiles.missionControlExecutorState({
+  profile: local, observation: modelessObservations[0], wrapper, verification,
+});
+assert.equal(modelessState.receipt_status, 'verified', 'regression needs a genuinely verified receipt');
+assert.equal(modelessState.cost_status, 'known', 'regression needs otherwise-trusted telemetry');
+assert.equal(modelessState.duration_status, 'known');
+assert.equal(modelessState.tokens_status, 'known');
+assert.equal(modelessState.observed_model, null);
+assert.equal(modelessState.model_status, 'unknown');
+assert.equal(modelessState.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+
+const modelessReplay = profiles.publicExecutorReplay({
+  profile: local, observation: modelessObservations[0], wrapper, verification,
+});
+assert.equal(modelessReplay.observed_model, null);
+assert.equal(modelessReplay.model_status, 'unknown');
+assert.equal(modelessReplay.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+assert(!['passed', 'verified'].includes(modelessReplay.model_status),
+  'public replay reported a verified model match without observed-model telemetry');
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
